  'v3.hero.intro_tag': { en: "AI coding agents waste tokens at every step.<br /><strong>RTK cuts the waste.</strong>", fr: "Les agents de code IA gaspillent des tokens à chaque étape.<br /><strong>RTK supprime ce gaspillage.</strong>", es: "Los agentes de código con IA desperdician tokens en cada paso.<br /><strong>RTK elimina ese desperdicio.</strong>", de: "KI-Coding-Agenten verschwenden bei jedem Schritt Tokens.<br /><strong>RTK streicht die Verschwendung.</strong>", zh: "AI 编程智能体在每一步都在浪费 token。<br /><strong>RTK 砍掉这些浪费。</strong>", ja: "AI コーディングエージェントは、あらゆる段階でトークンを無駄にしています。<br /><strong>RTK がその無駄を削ります。</strong>" },
  'v3.hero.scroll_cue': { en: 'See how it works', fr: 'Voir comment ça marche', es: 'Mira cómo funciona', de: 'So funktioniert es', zh: '看看它如何运作', ja: '仕組みを見る' },
  'v3.hero.pro_chip': { en: "<strong>RTK Pro</strong>: the control layer for every AI agent in your company", fr: "<strong>RTK Pro</strong> : la couche de contrôle de tous les agents IA de votre entreprise", es: "<strong>RTK Pro</strong>: la capa de control de todos los agentes de IA de tu empresa", de: "<strong>RTK Pro</strong>: die Kontrollschicht für jeden KI-Agenten in Ihrem Unternehmen", zh: "<strong>RTK Pro</strong>：贵公司所有 AI 智能体的控制层", ja: "<strong>RTK Pro</strong>：社内すべての AI エージェントのコントロールレイヤー" },
  'v3.hero.title': { en: "Fewer tokens<br /><em>More possibilities</em>", fr: "Moins de tokens<br /><em>Plus de possibilités</em>", es: "Menos tokens<br /><em>Más posibilidades</em>", de: "Weniger Tokens<br /><em>Mehr Möglichkeiten</em>", zh: "更少的 Token<br /><em>更多的可能</em>", ja: "トークンは少なく<br /><em>可能性は大きく</em>" },
  'v3.hero.descriptor': { en: "Command compressor · Cost reduction engine", fr: "Compresseur de commandes · Moteur de réduction des coûts", es: "Compresor de comandos · Motor de reducción de costes", de: "Befehls-Kompressor · Engine zur Kostensenkung", zh: "命令压缩器 · 降本引擎", ja: "コマンド圧縮 · コスト削減エンジン" },
  'v3.hero.sub': { en: "<strong>Up to 90% less</strong> command output. Install once, zero config.<span class=\"l2\"><strong>Up to 27% lower</strong> total cost with pipelines, in our benchmarks.</span>", fr: "<strong>Jusqu’à −90 %</strong> de sortie de commandes. Une installation, zéro config.<span class=\"l2\"><strong>Jusqu’à −27 %</strong> de coût total avec les pipelines, dans nos benchmarks.</span>", es: "<strong>Hasta un 90 % menos</strong> de salida de comandos. Una instalación, cero configuración.<span class=\"l2\"><strong>Hasta un 27 % menos</strong> de coste total con pipelines, en nuestros benchmarks.</span>", de: "<strong>Bis zu 90 % weniger</strong> Befehlsausgabe. Einmal installieren, null Konfiguration.<span class=\"l2\"><strong>Bis zu 27 % weniger</strong> Gesamtkosten mit Pipelines, in unseren Benchmarks.</span>", zh: "命令输出<strong>最多减少 90%</strong>。安装一次，零配置。<span class=\"l2\">使用 pipeline，总成本<strong>最多降低 27%</strong>（我们的基准测试）。</span>", ja: "コマンド出力を<strong>最大 90% 削減</strong>。インストールは一度、設定不要。<span class=\"l2\">パイプラインで総コストを<strong>最大 27% 削減</strong>（自社ベンチマーク）。</span>" },
  'v3.hero.more': { en: "Already using RTK? Unlock more savings", fr: "Vous utilisez déjà RTK ? Débloquez plus d’économies", es: "¿Ya usas RTK? Desbloquea más ahorro", de: "Du nutzt RTK schon? Hol mehr Ersparnis heraus", zh: "已经在用 RTK？解锁更多节省", ja: "すでに RTK をお使いですか？さらに節約を" },
  'v3.hero.cta_install_oss': { en: "Install RTK open source", fr: "Installer RTK open source", es: "Instalar RTK open source", de: "RTK Open Source installieren", zh: "安装开源版 RTK", ja: "RTK OSS をインストール" },
  'v3.hero.cta_install': { en: 'Install RTK', fr: 'Installer RTK', es: 'Instalar RTK', de: 'RTK installieren', zh: '安装 RTK', ja: 'RTK をインストール' },
  'v3.hero.cta_github': { en: 'View on GitHub', fr: 'Voir sur GitHub', es: 'Ver en GitHub', de: 'Auf GitHub ansehen', zh: '在 GitHub 查看', ja: 'GitHub で見る' },
  'v3.hero.meta': { en: "Free · Open source · Rust", fr: "Gratuit · Open source · Rust", es: "Gratis · Open source · Rust", de: "Kostenlos · Open Source · Rust", zh: "免费 · 开源 · Rust", ja: "無料 · オープンソース · Rust" },
  'v3.hero.visual_sr': { en: 'Diagram: a dense grid of tokens fills 86% of the AI context window, close to autocompact. It flows through the RTK filter, which strips the CLI output noise and leaves the meaningful lines: the same window back down to 73% used, with room to think.', fr: "Schéma : une grille dense de tokens occupe 86 % de la fenêtre de contexte de l'IA, proche du compactage automatique. Elle traverse le filtre RTK, qui retire le bruit des sorties CLI et conserve les lignes utiles : la même fenêtre redescend à 73 % utilisés, avec de la place pour raisonner.", es: 'Diagrama: una cuadrícula densa de tokens llena el 86 % de la ventana de contexto de la IA, cerca de la compactación automática. Pasa por el filtro de RTK, que elimina el ruido de la salida CLI y conserva las líneas útiles: la misma ventana baja al 73 % usado, con espacio para razonar.', de: 'Diagramm: ein dichtes Token-Raster füllt 86 % des KI-Kontextfensters, kurz vor dem automatischen Komprimieren. Es läuft durch den RTK-Filter, der das CLI-Ausgaberauschen entfernt und die sinnvollen Zeilen behält: dasselbe Fenster sinkt auf 73 % Auslastung, mit Raum zum Denken.', zh: '示意图：密集的 token 网格占满 AI 上下文窗口的 86%，接近自动压缩。它流经 RTK 过滤器，滤除 CLI 输出噪音并保留有意义的内容：同一窗口回落到 73% 占用，留出思考空间。', ja: '図：トークンの密なグリッドが AI コンテキストウィンドウの 86% を占め、自動圧縮の直前です。RTK フィルターを通ると CLI 出力のノイズが取り除かれ、意味のある行が残ります：同じウィンドウが 73% 使用まで下がり、考える余地が生まれます。' },
