  'v3.install.releases': { en: 'Download from Releases', fr: 'Télécharger depuis Releases', es: 'Descargar desde Releases', de: 'Von Releases herunterladen', zh: '从 Releases 下载', ja: 'Releases からダウンロード' },
  'v3.install.hook': { en: 'Then activate the auto-rewrite hook', fr: 'Activez ensuite le hook de réécriture automatique', es: 'Luego activa el hook de reescritura automática', de: 'Aktiviere dann den Auto-Rewrite-Hook', zh: '然后激活自动重写钩子', ja: '次に自動書き換えフックを有効化' },
