  'v3.install.note_cc': { en: 'Installs a PreToolUse hook in Claude Code settings.json: every Bash call is rewritten automatically.', fr: 'Installe un hook PreToolUse dans settings.json de Claude Code : chaque appel Bash est réécrit automatiquement.', es: 'Instala un hook PreToolUse en settings.json de Claude Code: cada llamada Bash se reescribe automáticamente.', de: 'Installiert einen PreToolUse-Hook in der settings.json von Claude Code: jeder Bash-Aufruf wird automatisch umgeschrieben.', zh: '在 Claude Code 的 settings.json 中安装 PreToolUse 钩子（）每次 Bash 调用都会被自动重写。', ja: 'Claude Code の settings.json に PreToolUse フックを追加し、すべての Bash 呼び出しを自動で書き換えます。' },
  'v3.install.note_cursor': { en: "Installs a preToolUse hook in Cursor hooks.json: shell commands are rewritten automatically.", fr: "Installe un hook preToolUse dans le hooks.json de Cursor : les commandes shell sont réécrites automatiquement.", es: "Instala un hook preToolUse en el hooks.json de Cursor: los comandos de shell se reescriben automáticamente.", de: "Installiert einen preToolUse-Hook in Cursors hooks.json: Shell-Befehle werden automatisch umgeschrieben.", zh: "在 Cursor 的 hooks.json 中安装 preToolUse 钩子：shell 命令会被自动重写。", ja: "Cursor の hooks.json に preToolUse フックをインストールします。シェルコマンドは自動的に書き換えられます。" },
  'v3.install.note_other': { en: "Or --gemini, --copilot, --opencode, and --agent <name> for the others. rtk init --help lists them all.", fr: "Ou --gemini, --copilot, --opencode, et --agent <nom> pour les autres. rtk init --help les liste tous.", es: "O --gemini, --copilot, --opencode, y --agent <nombre> para los demás. rtk init --help los muestra todos.", de: "Oder --gemini, --copilot, --opencode sowie --agent <Name> für die übrigen. rtk init --help listet alle auf.", zh: "也可使用 --gemini、--copilot、--opencode，其余智能体用 --agent <名称>。rtk init --help 会列出全部。", ja: "ほかに --gemini、--copilot、--opencode、その他は --agent <名前>。rtk init --help ですべて確認できます。" },

  'v3.cta.title': { en: 'Give your agent<br /><em>room to think</em>', fr: 'Donnez à votre agent<br /><em>de la place pour réfléchir</em>', es: 'Dale a tu agente<br /><em>espacio para pensar</em>', de: 'Gib deinem Agenten<br /><em>Raum zum Denken</em>', zh: '给你的代理<br />留出思考空间', ja: 'エージェントに<br />考える余地を' },
  'v3.cta.sub': { en: 'Build. Plug in. Share. In any agent.', fr: 'Construisez. Branchez. Partagez. Dans tous les agents.', es: 'Construye. Conecta. Comparte. En cualquier agente.', de: 'Bauen. Einbinden. Teilen. In jedem Agenten.', zh: '构建。接入。分享。在任何代理中。', ja: '構築。プラグイン。共有。どのエージェントでも。' },
